    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: What is the most common cause of choking in children?', '["Small toys", "Foods (e.g., hot dogs, grapes, hard candy)", "Coins", "Balloons"]', 1, 'Food items are the leading cause of choking and aspiration in toddlers. (Nelson)'),
    (v_topic_id, '202: Which of the following is the most dangerous household object for a child to ingest?', '["A penny", "A button battery", "A small plastic bead", "A piece of paper"]', 1, 'Button batteries can cause rapid tissue necrosis and esophageal perforation. (Harriet Lane)'),
    (v_topic_id, '203: A 3-year-old child presents after ingesting an unknown amount of acetaminophen. What is the standard antidote?', '["Naloxone", "N-acetylcysteine (NAC)", "Activated charcoal only", "Flumazenil"]', 1, 'NAC is highly effective if given early, ideally within 8 hours. (Case Files)'),
    (v_topic_id, '204: What is the toxic dose of acetaminophen in a child?', '["50 mg/kg", "100 mg/kg", "150 mg/kg", "200 mg/kg"]', 2, 'Ingestions >150 mg/kg are considered potentially hepatotoxic. (Nelson)'),
    (v_topic_id, '205: A child presents with vomiting, hematemesis, and abdominal pain after ingesting "vitamin pills." X-ray shows radiopaque tablets in the stomach. Diagnosis?', '["Vitamin C toxicity", "Iron poisoning", "Lead poisoning", "Zinc toxicity"]', 1, 'Iron is corrosive to the GI tract and appears radiopaque on X-ray. (Harriet Lane)'),
    (v_topic_id, '206: What is the antidote for severe iron poisoning?', '["Deferoxamine", "Dimercaprol", "Succimer", "Atropine"]', 0, 'Deferoxamine chelates iron, causing "vin rose" colored urine. (Nelson)'),
    (v_topic_id, '207: A child presents with tinnitus, hyperventilation, and metabolic acidosis. What did they likely ingest?', '["Acetaminophen", "Salicylates (Aspirin)", "Ibuprofen", "Iron"]', 1, 'Aspirin toxicity causes a mixed respiratory alkalosis and metabolic acidosis. (Case Files)'),
    (v_topic_id, '208: Why is aspirin avoided in children with viral illnesses (e.g., Influenza, Varicella)?', '["Risk of kidney failure", "Risk of Reye syndrome", "Risk of GI bleed", "Risk of Stevens-Johnson syndrome"]', 1, 'Reye syndrome causes acute encephalopathy and fatty degeneration of the liver. (Nelson)'),
    (v_topic_id, '209: What is the most common cause of death from poisoning in the home?', '["Lead", "Carbon monoxide", "Cleaning supplies", "Rat poison"]', 1, 'CO is a silent killer from faulty heaters or car exhaust. (CDC)'),
    (v_topic_id, '210: What is the treatment for carbon monoxide poisoning?', '["N-acetylcysteine", "100% oxygen", "Atropine", "Methylene blue"]', 1, 'Oxygen displaces CO from hemoglobin. (Harriet Lane)'),
    (v_topic_id, '211: A child presents with "blue" skin (cyanosis) that does not improve with oxygen. Pulse oximetry is ~85%. What is the likely diagnosis?', '["Pneumonia", "Methemoglobinemia", "Carbon monoxide poisoning", "Asthma"]', 1, 'Caused by nitrates or certain medications; treated with methylene blue. (Nelson)'),
    (v_topic_id, '212: What is the treatment for methemoglobinemia?', '["Activated charcoal", "Methylene blue", "Deferoxamine", "NAC"]', 1, 'Methylene blue reduces ferric iron (Fe3+) to ferrous iron (Fe2+). (Case Files)'),
    (v_topic_id, '213: At what age is a child typically ready for a booster seat?', '["4 years", "When they outgrow their forward-facing car seat (usually 4-8 years)", "8 years", "When they reach 4 feet 9 inches tall"]', 3, 'Children should use a booster until the vehicle seat belt fits correctly (typically at 4''9"). (AAP)'),
    (v_topic_id, '214: What is the leading cause of death in children between ages 1 and 4 years?', '["Cancer", "Drowning", "MVAs", "Pneumonia"]', 1, 'Drowning is the #1 cause of unintentional injury death in toddlers. (CDC)'),
    (v_topic_id, '215: What is the "Rule of 9s" for burns in children?', '["It is the same as adults", "It is modified because the head is proportionally larger in children", "It doesn''t apply", "It only measures the face"]', 1, 'The head accounts for ~18% in an infant vs 9% in an adult. (Harriet Lane)'),
    (v_topic_id, '216: A child presents with a "sunburn-like" rash that is painful. There are no blisters. This is a:', '["First-degree burn (Superficial)", "Second-degree burn (Partial thickness)", "Third-degree burn (Full thickness)", "Fourth-degree burn"]', 0, 'First-degree burns only involve the epidermis. (Nelson)'),
    (v_topic_id, '217: A child has a burn with blisters. This is a:', '["First-degree", "Second-degree", "Third-degree", "Chemical burn"]', 1, 'Blistering is characteristic of second-degree (partial-thickness) burns. (Case Files)'),
    (v_topic_id, '218: A child has a burn that is waxy, white, and painless. This is a:', '["First-degree", "Second-degree", "Third-degree", "Fourth-degree"]', 2, 'Third-degree burns destroy the nerve endings, making them painless. (Harriet Lane)'),
    (v_topic_id, '219: What is the "Parkland Formula" used for?', '["Dosing antibiotics", "Calculating fluid resuscitation in burn patients", "Measuring growth", "Dosing Tylenol"]', 1, 'Formula: 4 mL x Weight(kg) x %BSA burned. (Nelson)'),
    (v_topic_id, '220: At what age should screening for vision and hearing typically become more formal (e.g., using charts/audiology)?', '["At birth", "1 year", "3-4 years", "Entry into middle school"]', 2, 'Cooperation for formal screening is usually possible by age 3-4. (AAP)'),
    (v_topic_id, '221: Which of the following is a sign of "amblyopia" (lazy eye)?', '["Red eye", "Eye misalignment (strabismus) that is not corrected", "Itchy eyes", "Yellow discharge"]', 1, 'Uncorrected strabismus leads to the brain ignoring the image from one eye. (Nelson)'),
    (v_topic_id, '222: What is the "gold standard" for assessing pediatric obesity in children over 2 years?', '["Weight for height", "BMI-for-age percentile", "Waist circumference", "Skinfold thickness"]', 1, 'BMI percentiles are the standard for tracking growth and obesity. (CDC)'),
    (v_topic_id, '223: A 6-month-old infant is not tracking objects. Is this a concern?', '["No, vision matures at 1 year", "Yes, tracking should be present by 2-3 months", "No, it is normal", "Wait until 2 years"]', 1, 'Delayed visual milestones require urgent ophthalmology referral. (Case Files)'),
    (v_topic_id, '224: At what age should a child be able to use a spoon and fork?', '["12 months", "15-18 months", "3 years", "5 years"]', 1, 'Self-feeding with utensils is mastered in the second year. (Harriet Lane)'),
    (v_topic_id, '225: What is the maintenance fluid requirement for a 15-kg child?', '["1000 mL/day", "1250 mL/day", "1500 mL/day", "2000 mL/day"]', 1, '1000 (first 10) + 250 (5x50) = 1250 mL/day. (Nelson)'),
    (v_topic_id, '226: A child weighs 42 kg. What is their maintenance fluid rate?', '["42 mL/hr", "62 mL/hr", "82 mL/hr", "100 mL/hr"]', 2, '40 + 20 + 22 = 82 mL/hr. (Harriet Lane)'),
    (v_topic_id, '227: A 10-kg child has 5% dehydration. What is their fluid deficit?', '["100 mL", "500 mL", "1000 mL", "2000 mL"]', 1, '10kg x 0.05 = 0.5kg = 500 mL. (Case Files)'),
    (v_topic_id, '228: What is the preferred fluid for ORT?', '["Apple juice", "Sports drinks", "World Health Organization (WHO) ORS or commercial equivalent (e.g., Pedialyte)", "Water"]', 2, 'Standardized electrolyte/glucose ratios maximize absorption. (Nelson)'),
    (v_topic_id, '229: Why is "diluting formula" dangerous?', '["It saves money", "It can cause water intoxication and hyponatremic seizures", "It tastes bad", "It has too many calories"]', 1, 'Excess free water in infants leads to severe hyponatremia. (Harriet Lane)'),
    (v_topic_id, '230: What is the most common cause of hyperkalemia in a stable, asymptomatic child?', '["Renal failure", "Hemolysis of the blood sample (pseudohyperkalemia)", "Addison disease", "Excessive banana intake"]', 1, 'Always repeat the lab if it doesn''t match the clinical picture. (Case Files)'),
    (v_topic_id, '231: Which drug is used to treat "candidal diaper rash"?', '["Hydrocortisone", "Nystatin or Clotrimazole", "Mupirocin", "Acyclovir"]', 1, 'Antifungal creams are necessary for yeast. (Nelson)'),
    (v_topic_id, '232: What is the standard dose of Amoxicillin for acute otitis media?', '["20-30 mg/kg/day", "40-50 mg/kg/day", "80-90 mg/kg/day", "100-120 mg/kg/day"]', 2, 'High-dose amoxicillin is first-line to overcome resistant S. pneumoniae. (AAP)'),
    (v_topic_id, '233: At what age can a child safely consume honey?', '["Birth", "6 months", "12 months", "3 years"]', 2, 'Risk of infant botulism from C. botulinum spores. (Harriet Lane)'),
    (v_topic_id, '234: What is the first-line treatment for a child with "pinworms" (Enterobius)?', '["Albendazole or Pyrantel pamoate", "Amoxicillin", "Metronidazole", "Fluconazole"]', 0, 'Treat the child and often the whole family. (Case Files)'),
    (v_topic_id, '235: A child has an "umbilical hernia." When is surgery usually recommended?', '["Immediately at birth", "If it persists after age 4-5", "At 1 year", "Only if it is small"]', 1, 'Most umbilical hernias resolve spontaneously by school age. (Nelson)'),
    (v_topic_id, '236: A child has an "inguinal hernia." When is surgery recommended?', '["Watch and wait", "Urgently or Electively soon after diagnosis (due to risk of incarceration)", "After age 5", "Never"]', 1, 'Inguinal hernias do not resolve and risk bowel strangulation. (Harriet Lane)'),
    (v_topic_id, '237: What is the most common cause of neonatal hypoglycemia?', '["Maternal diabetes", "Prematurity", "IUGR", "All of the above"]', 3, 'Neonatal glucose regulation is sensitive to many factors. (Nelson)'),
    (v_topic_id, '238: Which of the following is a symptom of "congenital hypothyroidism"?', '["Hyperactivity", "Large tongue (macroglossia), constipation, and umbilical hernia", "Diarrhea", "Fast heart rate"]', 1, 'Early diagnosis via screening prevents "cretinism." (Case Files)'),
    (v_topic_id, '239: A child has "precocious puberty" and an enlarged adrenal gland. Diagnosis?', '["Congenital Adrenal Hyperplasia (CAH)", "Addison disease", "Diabetes", "Pituitary tumor"]', 0, 'CAH involves enzyme deficiencies leading to excess androgens. (Nelson)'),
    (v_topic_id, '240: What is the most common enzyme deficiency in CAH?', '["21-hydroxylase", "11-beta-hydroxylase", "17-alpha-hydroxylase", "5-alpha-reductase"]', 0, '21-hydroxylase deficiency accounts for >90% of cases. (Harriet Lane)'),
    (v_topic_id, '241: A child has "ambiguous genitalia" at birth. What is the most important immediate medical concern?', '["Gender assignment", "Salt-wasting crisis (Hypovolemic shock)", "Future fertility", "Surgical options"]', 1, 'CAH can cause life-threatening salt loss and hyperkalemia. (Case Files)'),
    (v_topic_id, '242: What is the most common cause of an "acute limp" with fever in a child?', '["Transient synovitis", "Septic arthritis", "Osteomyelitis", "Lyme disease"]', 1, 'In the setting of fever, septic arthritis must be excluded. (Nelson)'),
    (v_topic_id, '243: A child has a "clicking" hip on exam. Best initial imaging for DDH in an infant <4 months?', '["X-ray", "Ultrasound", "CT scan", "MRI"]', 1, 'Ultrasound is better for the cartilaginous hip of a young infant. (Harriet Lane)'),
    (v_topic_id, '244: What is the treatment for DDH in an infant <6 months?', '["Surgery", "Pavlik harness", "Cast", "Observation"]', 1, 'The harness holds the hip in flexion and abduction. (Case Files)'),
    (v_topic_id, '245: A 10-year-old child has a curvature of the spine. What is the most common type?', '["Congenital scoliosis", "Adolescent Idiopathic Scoliosis", "Neuromuscular scoliosis", "Kyphosis"]', 1, 'Idiopathic scoliosis is most common in pubertal girls. (Nelson)'),
    (v_topic_id, '246: What is the "Adam''s forward bend test" used for?', '["Assessing motor strength", "Screening for scoliosis", "Checking for meningitis", "Evaluating hip dysplasia"]', 1, 'Prominence of the rib hump indicates rotation. (Harriet Lane)'),
    (v_topic_id, '247: What is the most common cause of acute pharyngitis in children?', '["Group A Strep", "Viral (e.g., Adenovirus, Rhinovirus)", "EBV", "Diphtheria"]', 1, 'Most sore throats are viral. (Case Files)'),
    (v_topic_id, '248: A child has "vesicles" on the tonsillar pillars and soft palate. Diagnosis?', '["Strep throat", "Herpangina (Coxsackievirus)", "Herpetic gingivostomatitis", "Mononucleosis"]', 1, 'Herpangina involves the posterior pharynx. (Nelson)'),
    (v_topic_id, '249: What is the treatment for "Hand-Foot-and-Mouth" disease?', '["Antibiotics", "Acyclovir", "Supportive care (fluids, pain control)", "Steroids"]', 2, 'It is self-limiting and viral. (Harriet Lane)'),
    (v_topic_id, '250: At what age should a child have a BP of approximately 90/60 mmHg?', '["Neonate", "1-2 years", "10 years", "Adolescent"]', 1, 'BP increases steadily with age. (Nelson)'),
    (v_topic_id, '251: What is the average heart rate of a newborn?', '["60-80 bpm", "120-160 bpm", "80-100 bpm", "180-200 bpm"]', 1, 'Tachycardia is normal in neonates compared to adults. (Harriet Lane)'),
    (v_topic_id, '252: What is the average respiratory rate of a newborn?', '["12-20", "20-30", "40-60", "80-100"]', 2, 'Neonates breathe significantly faster than older children. (Case Files)'),
    (v_topic_id, '253: A child has "cyanosis" only when crying. Diagnosis?', '["Tetralogy of Fallot", "Breath-holding spell", "Pneumonia", "Normal"]', 1, 'Cyanotic breath-holding spells are benign. (Nelson)'),
    (v_topic_id, '254: What is the most common cause of neonatal seizures?', '["Hypocalcemia", "Hypoxic-Ischemic Encephalopathy (HIE)", "Infection", "Genetic disorders"]', 1, 'Birth asphyxia is the leading cause. (Harriet Lane)'),
    (v_topic_id, '255: A child has a "bulging fontanelle" and high fever. First step?', '["Head CT", "Lumbar puncture (LP)", "Observation", "X-ray"]', 1, 'LP is needed to rule out meningitis. (Case Files)'),
    (v_topic_id, '256: What is the most common cause of a simple febrile seizure?', '["High absolute temperature", "Rapid rate of rise in temperature", "Brain tumor", "Meningitis"]', 1, 'The speed of the fever spike is a major trigger. (Nelson)'),
    (v_topic_id, '257: What is the management for a simple febrile seizure (lasting <15 mins, non-focal)?', '["Start Phenobarbital", "Reassurance and fever control", "Daily Aspirin", "Brain MRI"]', 1, 'Simple febrile seizures are benign and don''t require chronic AEDs. (Harriet Lane)'),
    (v_topic_id, '258: A 12-month-old infant is not standing. Is this a red flag?', '["Yes", "No, they should walk by 15-18 months", "Wait until 2 years", "None"]', 1, 'Cutoff for walking is 15-18 months. (Case Files)'),
    (v_topic_id, '259: What is the most common cause of chronic cough in a child?', '["Asthma", "GERD", "Upper airway cough syndrome (post-nasal drip)", "All of the above"]', 3, 'These three make up the majority of cases. (Nelson)'),
    (v_topic_id, '260: A child "swallows a coin." Where is it most likely to get stuck?', '["Oropharynx", "Cricopharyngeus (Upper Esophageal Sphincter)", "Mid-esophagus", "Pylorus"]', 1, 'The first narrowing of the esophagus is the most common site. (Harriet Lane)'),
    (v_topic_id, '261: On X-ray, an esophageal coin appears as a:', '["Disk on the AP view", "Disk on the Lateral view", "It is not seen", "A line on AP view"]', 0, 'Esophageal coins lie in the coronal plane. (Case Files)'),
    (v_topic_id, '262: On X-ray, a tracheal coin (or object) appears as a:', '["Disk on the AP view", "Disk on the Lateral view", "A point", "None"]', 1, 'Tracheal objects lie in the sagittal plane. (Nelson)'),
    (v_topic_id, '263: What is the most common cause of epistaxis (nosebleed) in children?', '["Bleeding disorder", "Digital trauma (nose picking)", "Tumor", "Hypertension"]', 1, 'Trauma to Kiesselbach''s plexus is the #1 cause. (Harriet Lane)'),
    (v_topic_id, '264: How should a child with a nosebleed be positioned?', '["Leaning back", "Leaning forward with pressure on the nasal alae", "Lying flat", "Head between knees"]', 1, 'Leaning forward prevents blood from being swallowed/aspirated. (Case Files)'),
    (v_topic_id, '265: A child has "atopic dermatitis" and a secondary infection with yellow crusts. Organism?', '["S. aureus", "Strep pyogenes", "Both", "Candida"]', 2, 'Staph and Strep often infect eczematous skin. (Nelson)'),
    (v_topic_id, '266: What is the most common cause of pediatric hyperthyroidism?', '["Toxic nodule", "Graves Disease", "Thyroiditis", "Iodine excess"]', 1, 'Autoimmune stimulation of the TSH receptor. (Harriet Lane)'),
    (v_topic_id, '267: A child has "exophthalmos" (bulging eyes). Diagnosis?', '["Hypothyroidism", "Graves Disease", "Cushing disease", "Addison disease"]', 1, 'Classic finding in Graves. (Case Files)'),
    (v_topic_id, '268: What is the most common cause of pediatric hypothyroidism worldwide?', '["Hashimoto thyroiditis", "Iodine deficiency", "Surgical removal", "Pituitary failure"]', 1, 'In the US, Hashimoto''s is the most common. (Nelson)'),
    (v_topic_id, '269: A child has a "goiter" (enlarged thyroid). Is this hyper- or hypo-thyroidism?', '["Always hyper", "Always hypo", "Can be either", "Neither"]', 2, 'A goiter simply means the gland is enlarged. (Harriet Lane)'),
    (v_topic_id, '270: What is the classic triad of "Type 1 Diabetes" presentation?', '["Polyuria, Polydipsia, Weight loss", "Fever, Rash, Pain", "Obesity, High BP, Sleep apnea", "None"]', 0, 'Insulin deficiency leads to hyperglycemia and glycosuria. (Case Files)'),
    (v_topic_id, '271: A child with T1DM has fruity breath and vomiting. Diagnosis?', '["Hypoglycemia", "Diabetic Ketoacidosis (DKA)", "Gastroenteritis", "Alcohol ingestion"]', 1, 'DKA is a medical emergency. (Nelson)'),
    (v_topic_id, '272: What is the primary medical emergency in a child with "congenital adrenal hyperplasia"?', '["Gender assignment", "Adrenal crisis (hyponatremia, hyperkalemia, shock)", "Precocious puberty", "Tall stature"]', 1, 'Salt-wasting is life-threatening. (Harriet Lane)'),
    (v_topic_id, '273: A child has "precocious puberty" and "cafe-au-lait" spots. Diagnosis?', '["Neurofibromatosis type 1", "McCune-Albright syndrome", "Noonan syndrome", "Fragile X"]', 1, 'Classic triad includes polyostotic fibrous dysplasia. (Case Files)'),
    (v_topic_id, '274: A child has "cafe-au-lait" spots and "Lisch nodules" (iris hamartomas). Diagnosis?', '["Neurofibromatosis type 1", "NF type 2", "Tuberous sclerosis", "Sturge-Weber"]', 0, 'NF1 is common and requires monitoring for optic gliomas. (Nelson)'),
    (v_topic_id, '275: A child has "ash-leaf spots" and "shagreen patches." Diagnosis?', '["NF1", "Tuberous Sclerosis", "Sturge-Weber", "Ataxia telangiectasia"]', 1, 'TS is associated with seizures and cardiac rhabdomyomas. (Harriet Lane)'),
    (v_topic_id, '276: A child has a "port-wine stain" on the face. Diagnosis?', '["Hemangioma", "Sturge-Weber Syndrome", "Waardenburg syndrome", "Noonan syndrome"]', 1, 'Associated with leptomeningeal angiomatosis and glaucoma. (Case Files)'),
    (v_topic_id, '277: What is the most common cause of pediatric obesity?', '["Endocrine disorders", "Genetic syndromes", "Exogenous (caloric imbalance)", "Steroid use"]', 2, 'Simple obesity is by far the most common cause. (Nelson)'),
    (v_topic_id, '278: At what age should "universal" lipid screening occur?', '["Birth", "2 years", "9-11 years and 17-21 years", "Never"]', 2, 'Recommended by the AAP to identify familial dyslipidemias early. (AAP)'),
    (v_topic_id, '279: What is the most common cause of pediatric heart failure?', '["Myocarditis", "Congenital heart disease (left-to-right shunts)", "Cardiomyopathy", "Hypertension"]', 1, 'VSD/AVSD/PDA lead to volume overload. (Harriet Lane)'),
    (v_topic_id, '280: A 2-month-old infant is not fixing and following. Concern?', '["No, tracking starts at 6 months", "Yes, should fix and follow by 2 months", "Wait until 1 year", "Normal"]', 1, 'Visual fixation is an early milestone. (Case Files)'),
    (v_topic_id, '281: What is the "red reflex" used to screen for?', '["Cataracts", "Retinoblastoma", "Both", "Neither"]', 2, 'An abnormal (white) reflex is called leukocoria. (Nelson)'),
    (v_topic_id, '282: A child has a "white" red reflex (Leukocoria). Diagnosis?', '["Retinoblastoma", "Congenital cataract", "Either A or B", "Normal"]', 2, 'Both are vision- or life-threatening. (Harriet Lane)'),
    (v_topic_id, '283: What is the most common cause of hearing loss in children?', '["Congenital infection", "Chronic otitis media with effusion", "Genetic (Connexin 26)", "Meningitis"]', 1, 'Conductive hearing loss from fluid is very common. (Case Files)'),
    (v_topic_id, '284: A 12-month-old infant has "separation anxiety." Management?', '["Refer to psychiatry", "Reassure parents this is a normal milestone", "Encourage daycare immediately", "Start therapy"]', 1, 'Normal development of attachment. (Nelson)'),
    (v_topic_id, '285: At what age should a child start using a forward-facing car seat?', '["1 year", "When they outgrow rear-facing limits (ideally age 2+)", "4 years", "6 years"]', 1, 'Rear-facing is safer for the neck and spine. (AAP)'),
    (v_topic_id, '286: When can a child sit in the front seat of a car?', '["10 years", "13 years", "When they reach 5 feet", "After age 16"]', 1, 'Airbags can be lethal to smaller children. (CDC)'),
    (v_topic_id, '287: What is the maintenance fluid for a 65-kg child?', '["65 mL/hr", "85 mL/hr", "105 mL/hr", "125 mL/hr"]', 2, '40 + 20 + 45 = 105 mL/hr. (Harriet Lane)'),
    (v_topic_id, '288: What is the fluid deficit for a 20-kg child with 10% dehydration?', '["200 mL", "1000 mL", "2000 mL", "4000 mL"]', 2, '20kg x 0.10 = 2kg = 2000 mL. (Case Files)'),
    (v_topic_id, '289: A child is found unresponsive near a bottle of drain cleaner. Next step?', '["Induce vomiting with Ipecac", "Check airway and call Poison Control", "Give water to dilute", "Perform gastric lavage"]', 1, 'Ipecac is NO LONGER recommended and can cause more damage with corrosives. (Nelson)'),
    (v_topic_id, '290: A child "inhales" a peanut. Where is it most likely to go?', '["Left main bronchus", "Right main bronchus", "Stomach", "Trachea"]', 1, 'The right main bronchus is wider and more vertical. (Harriet Lane)'),
    (v_topic_id, '291: A child has a "staccato" cough. Organism?', '["RSV", "Pertussis", "Chlamydia trachomatis (in infants)", "Mycoplasma"]', 2, 'Classic description for neonatal chlamydial pneumonia. (Case Files)'),
    (v_topic_id, '292: What is the most common cause of pediatric pneumonia?', '["S. pneumoniae", "Viruses", "Mycoplasma", "Staph aureus"]', 1, 'Viruses cause most pneumonias in young children. (Nelson)'),
    (v_topic_id, '293: A child has "asymmetric" breath sounds and a sudden onset of coughing while eating peanuts. Diagnosis?', '["Asthma", "Foreign body aspiration", "Pneumonia", "Croup"]', 1, 'Asymmetry is a key clue to an aspirated object. (Harriet Lane)'),
    (v_topic_id, '294: What is the treatment for "nursemaid''s elbow"?', '["Surgery", "Reduction by supination and flexion", "Reduction by pronation", "Both B and C are effective"]', 3, 'Both maneuvers can successfully reduce the annular ligament. (Case Files)'),
    (v_topic_id, '295: A child has "honey-colored" crusts. Best topical treatment?', '["Hydrocortisone", "Mupirocin", "Ketoconazole", "Lidocaine"]', 1, 'Standard for impetigo. (Nelson)'),
    (v_topic_id, '296: At what age should a child have a vision of 20/20?', '["Birth", "2 years", "3-5 years", "10 years"]', 2, 'Visual acuity matures throughout early childhood. (Harriet Lane)'),
    (v_topic_id, '297: What is the most common cause of abdominal pain in a child with sickle cell disease?', '["Appendicitis", "Vaso-occlusive crisis (Splenic or mesenteric)", "Cholelithiasis", "All of the above"]', 3, 'Sickle cell patients have many unique causes of pain. (Nelson)'),
    (v_topic_id, '298: A child has "recurrent" UTIs. What imaging is needed?', '["Ultrasound", "VCUG (Voiding Cystourethrogram)", "Both", "None"]', 2, 'To look for structural abnormalities like VUR. (Case Files)'),
    (v_topic_id, '299: What is the most common cause of neonatal conjunctivitis on day 1 of life?', '["Gonorrhea", "Chlamydia", "Chemical (Silver Nitrate prophylaxis)", "HSV"]', 2, 'Chemical irritation is common immediately after birth. (Harriet Lane)'),
    (v_topic_id, '300: What is the treatment for Gonococcal conjunctivitis in a neonate?', '["Topical erythromycin", "IV/IM Ceftriaxone", "Oral Amoxicillin", "Observation"]', 1, 'Systemic treatment is required. (Nelson)'),
    (v_topic_id, '301: What is the most common complication of Chlamydia conjunctivitis in a neonate?', '["Blindness", "Pneumonia", "Meningitis", "Deafness"]', 1, 'Infants with chlamydial eye infection must be monitored for pneumonia. (Case Files)'),
    (v_topic_id, '302: At what age do children typically develop "object permanence"?', '["3 months", "6 months", "9 months", "12 months"]', 2, 'Understanding that an object exists when hidden. (Nelson)'),
    (v_topic_id, '303: A child can walk well, use 10 words, and stack 2 cubes. Age?', '["12 months", "15 months", "18 months", "24 months"]', 1, 'Classic 15-month milestones. (Harriet Lane)'),
    (v_topic_id, '304: A child can run, kick a ball, and use 50 words. Age?', '["18 months", "24 months", "3 years", "4 years"]', 1, 'Classic 2-year-old milestones. (Case Files)'),
    (v_topic_id, '305: A child can jump in place. Age?', '["18 months", "24 months", "3 years", "4 years"]', 1, 'Jumping in place is a 2-year skill. (Nelson)'),
    (v_topic_id, '306: A child can broad jump (forward). Age?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Broad jump is a 3-year skill. (Harriet Lane)'),
    (v_topic_id, '307: A child can use scissors. Age?', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Cutting with scissors is a 4-year-old fine motor skill. (Case Files)'),
    (v_topic_id, '308: A child can write their name. Age?', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Writing name is a 5-year-old milestone. (Nelson)'),
    (v_topic_id, '309: A child can tell a story. Age?', '["2 years", "3 years", "4 years", "5 years"]', 2, '4-year-olds can tell connected stories. (Harriet Lane)'),
    (v_topic_id, '310: A child understands "yesterday" and "tomorrow." Age?', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Time concepts develop around age 5. (Case Files)'),
    (v_topic_id, '311: At what age should a child be screened for iron deficiency anemia?', '["6 months", "12 months", "24 months", "Teens"]', 1, 'Recommended at 12 months for all children. (AAP)'),
    (v_topic_id, '312: What is the most common cause of accidental ingestion in children?', '["Lead", "Medications", "Plants", "Soaps"]', 1, 'Meds left in reach are a huge risk. (Nelson)'),
    (v_topic_id, '313: A child presents with "caustic" ingestion. Should you use activated charcoal?', '["Yes", "No, it obscures endoscopy and doesn''t bind well to corrosives", "Only if it is a base", "None"]', 1, 'Charcoal is avoided in caustic ingestions. (Harriet Lane)'),
    (v_topic_id, '314: What is the maintenance fluid for a 12-kg child?', '["1000 mL/day", "1100 mL/day", "1200 mL/day", "1500 mL/day"]', 1, '1000 + (2x50) = 1100 mL/day. (Case Files)'),
    (v_topic_id, '315: What is the maintenance fluid for a 25-kg child?', '["1500 mL/day", "1600 mL/day", "1750 mL/day", "2000 mL/day"]', 1, '1000 + 500 + (5x20) = 1600 mL/day. (Nelson)'),
    (v_topic_id, '316: A 4-kg infant needs maintenance fluids. Rate?', '["4 mL/hr", "8 mL/hr", "16 mL/hr", "20 mL/hr"]', 2, '4 mL/kg/hr x 4kg = 16 mL/hr. (Harriet Lane)'),
    (v_topic_id, '317: A 22-kg child needs maintenance fluids. Rate?', '["42 mL/hr", "62 mL/hr", "82 mL/hr", "100 mL/hr"]', 1, '40 (first 10) + 20 (next 10) + 2 (remaining 2) = 62 mL/hr. (Case Files)'),
    (v_topic_id, '318: A child has 10% dehydration and weighs 15 kg. What is the total deficit volume?', '["150 mL", "750 mL", "1500 mL", "3000 mL"]', 2, '15kg x 0.10 = 1.5kg = 1500 mL. (Nelson)'),
    (v_topic_id, '319: What is the "triple threat" of adolescent mortality?', '["MVA, Suicide, Homicide", "Cancer, Heart disease, Infection", "Drowning, Choking, Falls", "None"]', 0, 'Injury-related deaths dominate this age group. (CDC)'),
    (v_topic_id, '320: Final Pearl: What is the most important part of a pediatric physical exam?', '["Vitals", "Growth chart", "Observation of child-caregiver interaction and the child''s general appearance", "The stethoscope"]', 2, 'The clinical "look" of a child and how they relate to parents tells you the most. (MediHelp Mastery)');
